const items = $('Gmail Trigger').all();
const outputItems = [];

for (const item of items) {
  if (item.binary) {
    for (const key of Object.keys(item.binary)) {
      const binaryData = item.binary[key];
      const mimeType = binaryData.mimeType || '';
      const fileName = (binaryData.fileName || key).toLowerCase();

      // Skip if the file is an image (e.g., jpeg, png, etc.)
      if (mimeType.startsWith('image/') || fileName.endsWith('.jpg') || fileName.endsWith('.jpeg') || fileName.endsWith('.png')) {
        continue; // Skip this iteration and do not pass it to outputItems
      }

      outputItems.push({
        json: {
          fileName: binaryData.fileName || key,
          mimeType: binaryData.mimeType,
        },
        binary: {
          data: binaryData
        }
      });
    }
  }
}

return outputItems;

const newItems = [];

for (const item of $input.all()) {
  let rawOutput = item.json.output || '';

  // Clean markdown code blocks
  let cleanString = rawOutput.replace(/```json/g, '').replace(/```/g, '').trim();

  // Parse into actual JSON object
  let parsedData = JSON.parse(cleanString);
  let jsonStringFormatted = JSON.stringify(parsedData, null, 2);

  // Push the parsed data directly to json AND package as binary for the file writer
  newItems.push({
    json: parsedData, // This ensures your spreadsheet/file nodes see the actual extracted fields!
    binary: {
      data: {
        data: Buffer.from(jsonStringFormatted).toString('base64'),
        mimeType: 'application/json',
        fileName: 'extracted_lc_data.json',
      }
    }
  });
}

return newItems;
